<script setup lang="ts">
import { computed, ref, watch } from "vue"; import { useAppStore } from "../stores/app.js"; import { errorMessage,type ApiCalendar } from "../types";
const store=useAppStore();const calendar=ref<ApiCalendar>({occurrences:[],definitions:[],storyWorldId:"",startsAt:"",endsAt:""});const month=ref(new Date().toISOString().slice(0,7));const status=ref("准备加载日历……");const monthLabel=computed(()=>new Date(`${month.value}-01T00:00:00`).toLocaleDateString("zh-CN",{year:"numeric",month:"long"}));
async function loadCalendar(){if(!store.currentWorldId)return;const startsAt=new Date(`${month.value}-01T00:00:00.000Z`);if(Number.isNaN(startsAt.getTime())){status.value="请选择有效月份。";return}const endsAt=new Date(startsAt);endsAt.setUTCMonth(endsAt.getUTCMonth()+1);status.value="正在读取世界日历……";try{const result=await store.api.getWorldCalendar(store.currentWorldId,startsAt.toISOString(),endsAt.toISOString());calendar.value=result.data;status.value=`${calendar.value.occurrences.length} 个排期 · ${calendar.value.definitions.length} 个事件定义`;}catch(e:unknown){status.value=errorMessage(e)}}watch(()=>store.currentWorldId,()=>void loadCalendar(),{immediate:true});
</script>
<template><section class="calendar-page"><header class="page-header"><div><p>故事时间</p><h1>世界日程</h1><span>让每一次相遇都有值得期待的日期。</span></div><div class="header-right"><input type="month" v-model="month" @change="loadCalendar"/><small id="calendar-status">{{status}}</small><button @click="loadCalendar">刷新</button></div></header><div class="calendar-layout"><main><section class="schedule-card"><div class="section-title"><div><p>{{monthLabel}}</p><h2>即将发生</h2></div><span>{{calendar.occurrences.length}} 个安排</span></div><div v-if="calendar.occurrences.length" class="timeline"><article v-for="occ in calendar.occurrences" :key="occ.id"><time>{{new Date(occ.scheduledFor).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}}</time><i></i><div><strong>{{occ.eventKey}}</strong><p>{{new Date(occ.scheduledFor).toLocaleString()}}</p></div><em>{{occ.status}}</em></article></div><div v-else class="inner-empty">这个月还没有排期，给故事留一点空白也很好。</div></section></main><aside class="template-card"><div class="section-title"><div><p>事件库</p><h2>可用模板</h2></div><span>{{calendar.definitions.length}}</span></div><div v-if="calendar.definitions.length" class="template-list"><article v-for="def in calendar.definitions" :key="def.id"><span>{{def.triggerSource}}</span><strong>{{def.name}}</strong><small>优先级 {{def.priority}} · {{def.targetCharacterIds.length}} 位角色</small></article></div><div v-else class="inner-empty">还没有事件模板。</div></aside></div></section></template>
