l}.template-list{display:grid;gap:10px}.template-list article{display:grid;gap:7px;padding:13px;border-radius:13px;background:#fbf7f3}.template-list span{width:max-content;padding:3px 6px;border-radius:5px;background:#f2ded4;color:#aa654e;font-size:9px}.template-list strong{font-size:12px}.template-list small{color:#a3978e;font-size:10px}.inner-empty{padding:45px 10px;color:#aa9d94;text-align:center;font-size:12px;line-height:1.7}@media(max-width:1000px){.calendar-layout{grid-template-columns:1fr}.calendar-page{padding:30px}}
